<?php
namespace App\Http\Controllers;
use App\Models\{AttendanceRecord,Donation,Member};use Carbon\Carbon;use Inertia\{Inertia,Response};
class DashboardController extends Controller {public function __invoke():Response{$now=now();$months=collect(range(5,0))->map(fn($i)=>$now->copy()->subMonths($i)->startOfMonth());$membershipTrend=$months->map(fn(Carbon $m)=>['label'=>$m->format('M'),'value'=>Member::where('join_date','<=',$m->copy()->endOfMonth())->count()]);$donationTrend=$months->map(fn(Carbon $m)=>['label'=>$m->format('M'),'value'=>(float)Donation::whereBetween('donation_date',[$m,$m->copy()->endOfMonth()])->where('status','completed')->sum('amount')]);$attendance=AttendanceRecord::where('attendance_date','>=',$now->copy()->subDays(30));$attendanceRate=Member::where('status','active')->count()>0?round(($attendance->distinct('member_id')->count('member_id')/Member::where('status','active')->count())*100,1):0;return Inertia::render('Dashboard',['metrics'=>['members'=>Member::count(),'activeMembers'=>Member::where('status','active')->count(),'newThisMonth'=>Member::whereBetween('join_date',[$now->copy()->startOfMonth(),$now->copy()->endOfMonth()])->count(),'attendanceRate'=>$attendanceRate,'givingYtd'=>(float)Donation::whereYear('donation_date',$now->year)->where('status','completed')->sum('amount')],'membershipTrend'=>$membershipTrend,'donationTrend'=>$donationTrend,'recentMembers'=>Member::latest()->limit(5)->get(['id','first_name','last_name','status','join_date']),'recentAttendance'=>AttendanceRecord::with('member:id,first_name,last_name')->latest('check_in_time')->limit(6)->get()]);}}
